-- T-463 (2026-10-23) — the AI feature switch (ADR-0037 addendum, ADR-0030 §6):
-- the owner's super user turns an AI feature off or on for one project, with a
-- reason, and every throw is kept with the person's name. Drawn in
-- docs/build/data-model.md, drawer 7. Generated by drizzle-kit; the append-only
-- trigger and the grant at the foot are hand-added, as every trigger in this
-- repo is.
CREATE TABLE "ai_feature_switches" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"project_id" uuid NOT NULL,
	"feature" text NOT NULL,
	"enabled" boolean NOT NULL,
	"reason" text NOT NULL,
	"changed_by_participant_id" uuid NOT NULL,
	"changed_at" timestamp with time zone DEFAULT now() NOT NULL
);
