-- Append-only (T-008's trigger): a record of what a project decided the AI may
-- do that its own super user could rewrite answers nothing.
CREATE TRIGGER ai_feature_switches_append_only
  BEFORE UPDATE OR DELETE ON ai_feature_switches
  FOR EACH ROW EXECUTE FUNCTION forbid_mutation();
